cypress_script:
describe('Tool Shop Product Catalogue', () => {
  it('should filter eco-friendly products successfully', () => {
    cy.visit('https://practicesoftwaretesting.com/');
    cy.get('[data-test="eco-friendly-filter"]').check();
    cy.get('[data-test="search-submit"]').click();
    // Assert that the URL reflects the filter action
    cy.url().should('include', 'eco_friendly=true');
  });

  it('should not return results when filtering without selecting any items', () => {
    cy.visit('https://practicesoftwaretesting.com/');
    cy.get('[data-test="search-submit"]').click();
    // Assert that the current URL is still the homepage
    cy.url().should('eq', 'https://practicesoftwaretesting.com/');
  });
});

playwright_script:
test.describe('Tool Shop Product Catalogue', () => {
  test('should filter eco-friendly products successfully', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/');
    await page.check('[data-test="eco-friendly-filter"]');
    await page.click('[data-test="search-submit"]');
    // Assert that the URL reflects the filter action
    await page.waitForURL('https://practicesoftwaretesting.com/?eco_friendly=true');
  });

  test('should not return results when filtering without selecting any items', async ({ page }) => {
    await page.goto('https://practicesoftwaretesting.com/');
    await page.click('[data-test="search-submit"]');
    // Assert that the current URL is still the homepage
    await page.waitForURL('https://practicesoftwaretesting.com/');
  });
});
